-- A2 plan: lessons 2–8 (library, published). Written by hand; each lesson uses library tasks and practice.
-- Idempotent by title; position = order in the A2 plan ("My weekend" is position 0).
insert into public.study_lessons (author_id, scope, status, title, description, cefr, topic, duration_min, source, position, content)
select (select id from public.profiles where role = 'admin' order by created_at limit 1), 'library', 'published', v.title, v.description, 'A2', v.topic, v.duration, 'manual', v.pos, v.content::jsonb
from (values
(
  'Then and now', 'Compare your life before and now with was / were: I was shy, we were at school, were you…?', 'Culture', 50, 1,
  $json${"stages": [
    {"kind": "warmup", "title": "Baby photos", "minutes": 5,
     "teacher": "Show (or describe) a photo of yourself as a child. Students guess: How old were you? Where were you? Then they ask each other the same questions.",
     "body": "Think about yourself at 7 years old. Answer:\n• Where were you?\n• Who was your best friend?\n• What was your favourite cartoon or game?",
     "examples": ["I was in Odesa with my grandparents.", "My best friend was Max.", "My favourite game was Minecraft."], "task_id": null},
    {"kind": "presentation", "title": "Was / were", "minutes": 10,
     "teacher": "Show that was goes with I / he / she / it and were with you / we / they. Questions don’t use did: “Were you tired?”, not “Did you be tired?”.",
     "body": "**I / he / she / it was** — I was shy.\n**You / we / they were** — We were in the same class.\n**Negative:** wasn’t / weren’t — It wasn’t easy.\n**Question:** **Was** it fun? **Were** you scared? — Yes, I was. / No, we weren’t.\n**Where were you…? Who was…? How old were you…?**\nTime words: when I was a child, last year, in 2019, yesterday.",
     "examples": ["When I was ten, I was really shy.", "My parents were students in 2005.", "The test wasn’t difficult.", "Where were you last night? — I was at home."], "task_id": null},
    {"kind": "tasks", "title": "Practice: was or were?", "minutes": 12,
     "teacher": "Students do the exercises. For each answer, ask: one person or many?",
     "body": "Choose or write was / were.", "examples": [], "task_id": "caa777da-cd62-47ef-8db3-f6600feb1af2"},
    {"kind": "practice", "title": "Reading: My new hobby", "minutes": 10,
     "teacher": "Read the text together. Students find every was / were and say how the man’s life changed.",
     "body": "Read about a man who started a new hobby and answer the questions.", "examples": [], "task_id": "179017ed-17aa-4d7e-8f3b-2a6bef51987e"},
    {"kind": "production", "title": "Then vs now", "minutes": 10,
     "teacher": "Pairs compare their life 5 years ago and now: school, friends, hobbies, music. Then each student shares the biggest change.",
     "body": "Tell your partner how your life was 5 years ago and how it is now. Use was / were and is / are.",
     "examples": ["Five years ago I was in primary school. Now I’m at university.", "My hair was blue! Now it is brown.", "My favourite singers were… Now I listen to…"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework. It can be a text post with two photos.",
     "body": "Write a “Then and now” post (8 sentences): you or your town 5–10 years ago and today.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'Food and shopping', 'Talk about food and shopping: countable and uncountable nouns, some / any, much / many / a lot of.', 'Shopping', 55, 2,
  $json${"stages": [
    {"kind": "warmup", "title": "Fridge check", "minutes": 5,
     "teacher": "Ask students what is in their fridge right now. Write the words in two columns on the board (things you can count / can’t count) without explaining yet.",
     "body": "What’s in your fridge right now? Name 6 things.",
     "examples": ["some milk", "three eggs", "cheese", "two apples", "juice"], "task_id": null},
    {"kind": "presentation", "title": "Countable and uncountable", "minutes": 10,
     "teacher": "Use the two columns from the warm-up. Show some (positive) / any (negatives and questions), many (countable) / much (uncountable), a lot of (both). Mention tricky words: money, bread, homework, advice.",
     "body": "**Countable:** an apple, two apples — **many** apples, **a few** apples.\n**Uncountable:** water, bread, money — **much** water, **a little** water (no a / an, no plural).\n**some** in positive sentences: We need **some** milk.\n**any** in negatives and questions: Is there **any** bread? We haven’t got **any** eggs.\n**a lot of** works with both: a lot of apples, a lot of money.\n**How many** apples? **How much** milk? **How much** is it? (price)",
     "examples": ["We need some tomatoes and some cheese.", "There isn’t any milk left.", "How many eggs do we need?", "I don’t have much money, but I have a lot of coupons!"], "task_id": null},
    {"kind": "tasks", "title": "Practice: some or any?", "minutes": 10,
     "teacher": "Students do the exercises. Ask: can we count it?",
     "body": "Choose some / any, a / an or the plural.", "examples": [], "task_id": "1098ea90-bec9-4a61-8e3f-7347a2038319"},
    {"kind": "tasks", "title": "Practice: much, many, a lot of", "minutes": 8,
     "teacher": "A short practice. Point out that in positive sentences a lot of sounds more natural than much.",
     "body": "Choose much, many or a lot of.", "examples": [], "task_id": "a05752e5-bd12-4d0f-b0f6-a38bed144d8d"},
    {"kind": "practice", "title": "Reading: Saturday at the market", "minutes": 10,
     "teacher": "Read the text. Students list everything Tom and his grandfather buy and mark which words are countable.",
     "body": "Read about Tom’s Saturday and answer the questions.", "examples": [], "task_id": "dd1e0a4a-da34-48b4-8e7e-49c90d3f543c"},
    {"kind": "production", "title": "Party shopping list", "minutes": 10,
     "teacher": "Groups plan food for a party for 10 friends with a small budget. They write a list and ask questions with How many / How much. Each group presents its list.",
     "body": "You are having a party for 10 friends. Make a shopping list together and decide how much / how many you need.",
     "examples": ["We need a lot of pizza — maybe five big ones.", "How much juice do we need? — About four bottles.", "We don’t need any cake: Anna is bringing one!"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 2,
     "teacher": "Explain the homework.",
     "body": "Write your favourite recipe (or a dish from your family) in English: the ingredients with some / a / a lot of and 5 steps.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'The best and the worst', 'Compare things and give strong opinions: bigger, more interesting, the best, the worst.', 'Daily Life', 55, 3,
  $json${"stages": [
    {"kind": "warmup", "title": "This or that?", "minutes": 5,
     "teacher": "Say pairs quickly: cats or dogs? summer or winter? TikTok or YouTube? Students choose and give one reason with an adjective.",
     "body": "Choose and say why: cats or dogs? summer or winter? films or series?",
     "examples": ["Dogs — they are funny.", "Winter — it’s cosy.", "Series — they are long."], "task_id": null},
    {"kind": "presentation", "title": "Comparatives and superlatives", "minutes": 12,
     "teacher": "Build the table on the board with short adjectives (-er / -est), long ones (more / the most) and irregular ones. Remind them: than after comparatives, the before superlatives, and never “more cheaper”.",
     "body": "**Short adjectives:** cheap → cheap**er** → the cheap**est**; big → bi**gg**er → the bi**gg**est; easy → eas**ier** → the eas**iest**.\n**Long adjectives:** interesting → **more** interesting → **the most** interesting.\n**Irregular:** good → better → the best; bad → worse → the worst; far → further → the furthest.\n**Comparative + than:** My phone is older **than** yours.\n**Superlative with the:** It’s **the best** day **of** my life / **in** the world.",
     "examples": ["This hoodie is cheaper than that one.", "Maths is more difficult than English for me.", "It’s the funniest video on the internet.", "That was the worst film I’ve ever seen!"], "task_id": null},
    {"kind": "tasks", "title": "Practice: comparatives", "minutes": 10,
     "teacher": "Students do the exercises. Ask them to say the rule for each answer: short, long or irregular?",
     "body": "Write or choose the comparative form.", "examples": [], "task_id": "7e4d0b52-51d7-4c22-bfb0-2e521e6a1084"},
    {"kind": "practice", "title": "Practice: superlatives", "minutes": 10,
     "teacher": "Students do the exercises. Remind them about the.",
     "body": "Write or choose the superlative form.", "examples": [], "task_id": "4e81c311-9422-4b9c-9cac-ca754334c326"},
    {"kind": "production", "title": "Class awards", "minutes": 15,
     "teacher": "Groups create “awards” for things, not people (to keep it kind): the best song of the year, the most boring school subject, the most useful app, the worst food in the canteen. They argue and vote, then present the winners with reasons.",
     "body": "Make your own awards in groups: the best…, the most…, the worst… Compare the candidates and choose a winner.",
     "examples": ["The most useful app is Maps, because it’s faster than asking people.", "The worst food is the soup — it’s colder than ice!"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write a short review “Top 3” (songs, games, places or series): compare them and say which is the best and why (8–10 sentences).",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'How often?', 'Talk about hobbies and habits with always, usually, often, sometimes, rarely, never — and compare habits with what is happening now.', 'Culture', 50, 4,
  $json${"stages": [
    {"kind": "warmup", "title": "Never have I ever (easy version)", "minutes": 5,
     "teacher": "Read simple statements (I play games every day. I go to bed after midnight. I eat breakfast.). Students raise a hand if it’s true for them. Ask a few: How often?",
     "body": "Listen to the statements. Is it true for you? How often do you do it?",
     "examples": ["I play games every day.", "I sometimes go to bed after midnight."], "task_id": null},
    {"kind": "presentation", "title": "Adverbs of frequency", "minutes": 10,
     "teacher": "Draw a line from 0% to 100% and put the adverbs on it. Show the word order: before the main verb, after be. Then contrast habits (Present Simple) with now (Present Continuous).",
     "body": "**always** (100%) → **usually** → **often** → **sometimes** → **rarely / hardly ever** → **never** (0%)\nBefore the main verb: I **often** play tennis.\nAfter be: She **is always** late.\nAlso: every day, once a week, twice a month.\n**How often** do you…?\n\nHabit vs now: I **usually** listen to rap, but today I**’m listening** to jazz.",
     "examples": ["I always check my phone in the morning.", "We rarely eat fast food.", "He is never on time!", "How often do you go to the gym? — Twice a week."], "task_id": null},
    {"kind": "tasks", "title": "Practice: always, often, never", "minutes": 12,
     "teacher": "Students do the exercises. Check the word order out loud.",
     "body": "Put the adverb in the right place or choose the right one.", "examples": [], "task_id": "86a6918e-5c35-476d-a278-c2a2f690495b"},
    {"kind": "practice", "title": "Practice: usually vs right now", "minutes": 10,
     "teacher": "Present Continuous practice. Ask students to make one “usually … but now …” sentence after the exercises.",
     "body": "Choose the Present Simple or the Present Continuous.", "examples": [], "task_id": "aec35af9-4a74-4a15-b30e-8387880599db"},
    {"kind": "production", "title": "Hobby survey", "minutes": 10,
     "teacher": "Students interview 3 classmates about hobbies (sport, music, games, reading, drawing) with How often…? Then they report the results: Most people…, Nobody…",
     "body": "Ask 3 classmates how often they do 5 hobbies. Then tell the class what you found.",
     "examples": ["How often do you draw? — Hardly ever.", "Two people play the guitar every day.", "Nobody reads on the bus!"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write about your week: what you always, usually, sometimes and never do — and one thing that is different this week (8 sentences).",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'Summer plans', 'Talk about plans and predictions with be going to: I’m going to…, it’s going to rain!', 'Travel', 50, 5,
  $json${"stages": [
    {"kind": "warmup", "title": "Dream holiday", "minutes": 5,
     "teacher": "Ask: Where do you want to go this summer? What do you want to do? Write useful phrases on the board: go to the sea, visit…, learn to…, get a job.",
     "body": "Answer the questions:\n• Where do you want to go this summer?\n• What do you want to learn or try?",
     "examples": ["I want to go to the sea.", "I want to learn to surf."], "task_id": null},
    {"kind": "presentation", "title": "Be going to", "minutes": 10,
     "teacher": "Show the form am / is / are + going to + verb. Explain two uses: plans you already decided, and predictions from what you can see now. Mention that people say “gonna” in fast speech, but write going to.",
     "body": "**Plans (already decided):** I**’m going to** visit my cousins in July.\n**Predictions (you can see it):** Look at those clouds — it**’s going to** rain!\n**Form:** am / is / are + going to + verb.\n**Negative:** I’m **not going to** stay at home.\n**Question:** **Are** you **going to** travel? What **are** you **going to** do?\nTime words: this summer, next week, tomorrow, in August.",
     "examples": ["We’re going to camp by the lake.", "She’s going to get a summer job.", "I’m not going to sleep all day… maybe.", "Careful! You’re going to drop your phone!"], "task_id": null},
    {"kind": "tasks", "title": "Practice: going to", "minutes": 12,
     "teacher": "Students do the exercises. Ask: is it a plan or a prediction?",
     "body": "Choose or write the right form of be going to.", "examples": [], "task_id": "8df10aac-c71d-4ee6-888b-b0c640400076"},
    {"kind": "practice", "title": "Listening: Plans for Saturday", "minutes": 10,
     "teacher": "Play the recording twice. First time: where are they going? Second time: answer the questions. Then find the phrases for making plans in the script.",
     "body": "Listen to two friends making plans and answer the questions.", "examples": [], "task_id": "f342d724-4f3f-4929-a0b0-94a5f3bb6400"},
    {"kind": "production", "title": "Plan a trip", "minutes": 10,
     "teacher": "Pairs plan a 3-day summer trip with a small budget: where, how, where to sleep, what to do each day. They present the plan; the class votes for the best trip.",
     "body": "Plan a 3-day summer trip with a partner. Present your plan with going to.",
     "examples": ["We’re going to take the night train to Lviv.", "On day two we’re going to visit the old town.", "We aren’t going to stay in a hotel — it’s too expensive."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write a message to a friend about your plans for the summer (or the next holidays): 6–8 sentences with going to, and one question for your friend.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'Rules, rules, rules', 'Talk about rules and obligations: must, mustn’t, have to, don’t have to.', 'Daily Life', 50, 6,
  $json${"stages": [
    {"kind": "warmup", "title": "Signs", "minutes": 5,
     "teacher": "Describe or show signs (no phones, wear a helmet, no swimming, quiet please). Students guess where you can see them.",
     "body": "Where can you see these signs? What do they mean?\n• No phones\n• Wear a helmet\n• Quiet, please",
     "examples": ["In an exam room.", "In a skatepark.", "In a library."], "task_id": null},
    {"kind": "presentation", "title": "Must and have to", "minutes": 12,
     "teacher": "Show that must and have to both mean it is necessary. The big difference is in the negative: mustn’t = it’s not allowed; don’t have to = it’s not necessary. Use a school example for each.",
     "body": "**must** + verb — it’s necessary (often the speaker’s opinion or a written rule): You **must** wear a helmet.\n**have to / has to** + verb — it’s necessary (a rule from outside): I **have to** wear a uniform.\n**mustn’t** = it’s NOT allowed: You **mustn’t** use your phone in the exam.\n**don’t have to** = it’s NOT necessary: We **don’t have to** go to school on Saturday.\n**Question:** **Do** you **have to** …?\nPast: **had to** — I had to get up at six.",
     "examples": ["Students must be quiet in the library.", "She has to walk her dog every morning.", "You mustn’t swim here — it’s dangerous.", "You don’t have to come, but it’ll be fun!"], "task_id": null},
    {"kind": "tasks", "title": "Practice: must or have to?", "minutes": 12,
     "teacher": "Students do the exercises. Spend extra time on mustn’t vs don’t have to.",
     "body": "Choose must, mustn’t, have to or don’t have to.", "examples": [], "task_id": "6e3b7345-f319-4983-bf68-c0aa47d11288"},
    {"kind": "practice", "title": "Reading: At the sports centre", "minutes": 8,
     "teacher": "An easy text with real rules. Students rewrite 3 rules with must / mustn’t / have to / don’t have to.",
     "body": "Read the notice. Then say 3 rules with must, have to or don’t have to.", "examples": [], "task_id": "56707d8c-2f62-45aa-961f-843ca61a3288"},
    {"kind": "production", "title": "Our rules", "minutes": 10,
     "teacher": "Groups write 6 fun but realistic rules for something they know: a group chat, a gaming team, a flat with roommates, our English class. They present them; the class votes for the fairest set.",
     "body": "Write rules for a group chat, a gaming team or a shared flat (6 rules). Use must, mustn’t, have to and don’t have to.",
     "examples": ["You mustn’t send voice messages longer than one minute.", "Everyone has to wash their own dishes.", "You don’t have to answer at night."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write about the rules at your school, work or home (8 sentences). Which rule do you think is unfair? Why?",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'Promises and predictions', 'Make promises, offers and quick decisions, and predict the future with will.', 'Transport', 50, 7,
  $json${"stages": [
    {"kind": "warmup", "title": "In 20 years", "minutes": 5,
     "teacher": "Ask: What will the world be like in 20 years? Students make quick guesses about phones, cars, school, food.",
     "body": "What will the world be like in 20 years? Make 3 guesses.",
     "examples": ["Cars will drive themselves.", "People won’t use cash."], "task_id": null},
    {"kind": "presentation", "title": "Will", "minutes": 10,
     "teacher": "Show will + verb for predictions (opinion), promises, offers and decisions made right now. Contrast it with going to (a plan made before). Remind them: no will after if / when about the future.",
     "body": "**will + verb** (’ll) — the same for everyone.\n**Predictions (your opinion):** I think it **will** be sunny. You**’ll** love this song.\n**Promises:** I**’ll** call you tonight, I promise.\n**Offers:** I**’ll** help you with that box.\n**Decisions right now:** I’m cold. I**’ll** close the window.\n**Negative:** **won’t** (will not). **Question:** **Will** you…?\n**will** = decided now; **going to** = planned before.",
     "examples": ["Don’t worry, I won’t tell anyone.", "I think our team will win.", "The pizza is here! — OK, I’ll pay.", "Will you be at the party?"], "task_id": null},
    {"kind": "tasks", "title": "Practice: will", "minutes": 12,
     "teacher": "Students do the exercises. Ask: is it a promise, an offer, a prediction or a quick decision?",
     "body": "Choose or write will / won’t.", "examples": [], "task_id": "f1351e70-6322-4f93-8628-197da5259803"},
    {"kind": "practice", "title": "Listening: At the train station", "minutes": 10,
     "teacher": "Play the announcements twice. Students note the times and platforms, and every “will” they hear.",
     "body": "Listen to the station announcements and answer the questions.", "examples": [], "task_id": "38bcbad5-a007-4405-a482-351e73120a54"},
    {"kind": "production", "title": "Fortune teller", "minutes": 10,
     "teacher": "Students write 3 funny but kind predictions for a partner (next week, next year, in 10 years) on paper and read them out. The partner reacts with a promise or decision: “Then I’ll…”.",
     "body": "Write 3 predictions for your partner. Your partner reacts with a promise or a decision.",
     "examples": ["Next week you’ll find money in your old jeans.", "In ten years you’ll be a famous streamer! — Then I’ll buy a big house for my mum."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write 5 predictions about your life in 10 years and 3 promises to yourself for this year.",
     "examples": [], "task_id": null}
  ]}$json$
)
) as v(title, description, topic, duration, pos, content)
where not exists (select 1 from public.study_lessons s where s.title = v.title and s.scope = 'library');
